-- 模块:表格生成器/数据/wx：tools/build_tablegen_data.py 由 [[荒野天气]]、[[天气]]、[[环境规则]] 页里的随机表拆成（别手改）。格式见脚本说明。
return [=====[{"荒野天气":{"sec":{},"tab":{"表4-12：气候基线":[[null,null,"寒冷","20°F","30°F","40°F","30°F","频率和强度各降低一级"],[null,null,"温带","30°F","60°F","80°F","60°F","—"],[null,null,"热带","50°F","75°F","95°F","75°F","频率和强度各提高一级"]],"表4-13：海拔基线":[[null,null,"海平面","低于1,000尺","+10°F","重度"],[null,null,"低地","1,000尺至5,000尺","—","中度"],[null,null,"高地","高于5,000尺","-10°F","中度（降水频率降低一级）"]],"表4-14：季节基线":[[null,null,"春","间歇","常见"],[null,null,"夏","常见","间歇"],[null,null,"秋","间歇","常见"],[null,null,"冬","罕见","罕见"]],"表4-15：寒冷地区气温变化":[[1,20,"-3d10°F","1d4天"],[21,40,"-2d10°F","1d6+1天"],[41,60,"-1d10°F","1d6+2天"],[61,80,"无变化","1d6+2天"],[81,95,"+1d10°F","1d6+1天"],[96,99,"+2d10°F","1d4天"],[100,100,"+3d10°F","1d2天"]],"表4-16：温带地区气温变化":[[1,5,"-3d10°F","1d2天"],[6,15,"-2d10°F","1d4天"],[16,35,"-1d10°F","1d6+1天"],[36,65,"无变化","1d6+1天"],[66,85,"+1d10°F","1d6+1天"],[86,95,"+2d10°F","1d4天"],[96,100,"+3d10°F","1d2天"]],"表4-17：热带地区气温变化":[[1,10,"-2d10°F","1d2天"],[11,25,"-1d10°F","1d2天"],[26,55,"无变化","1d4天"],[56,85,"+1d10°F","1d4天"],[86,100,"+2d10°F","1d2天"]],"表4-18：每日降水几率":[[null,null,"干旱","5%（降水强度降低2级）"],[null,null,"罕见","15%"],[null,null,"间歇","30%"],[null,null,"常见","60%"],[null,null,"持续","95%"]],"表4-19：轻度非冻结降水":[[1,20,"薄雾","1d8小时"],[21,40,"中雾","1d6小时"],[41,50,"毛毛雨","1d4小时"],[51,75,"毛毛雨","2d12小时"],[76,90,"小雨","1d4小时"],[91,100,"小雨（低于40°F时为冻雨）","1小时"]],"表4-20：轻度冻结降水":[[1,20,"薄雾","1d6小时"],[21,40,"薄雾","1d8小时"],[41,50,"中雾","1d4小时"],[51,60,"小雪","1小时"],[61,75,"小雪","1d4小时"],[76,100,"小雪","2d12小时"]],"表4-21：中度非冻结降水":[[1,10,"中雾","1d8小时"],[11,20,"中雾","1d12小时"],[21,30,"浓雾","1d4小时"],[31,35,"雨","1d4小时"],[36,70,"雨","1d8小时"],[71,90,"雨","2d12小时"],[91,100,"雨（低于40°F时为冻雨）","1d4小时"]],"表4-22：中度冻结降水":[[1,10,"中雾","1d6小时"],[11,20,"中雾","1d8小时"],[21,30,"浓雾","1d4小时"],[31,50,"中雪","1d4小时"],[51,90,"中雪","1d8小时"],[91,100,"中雪","2d12小时"]],"表4-23：重度非冻结降水":[[1,10,"浓雾","1d8小时"],[11,20,"浓雾","2d6小时"],[21,50,"大雨","1d12小时"],[51,70,"大雨","2d12小时"],[71,85,"大雨（低于40°F时为冻雨）","1d8小时"],[86,90,"雷暴","1小时"],[91,100,"雷暴","1d3小时"]],"表4-24：重度冻结降水":[[1,10,"中雾","1d8小时"],[11,20,"浓雾","2d6小时"],[21,60,"小雪","2d12小时"],[61,90,"中雪","1d8小时"],[91,100,"大雪","1d6小时"]],"表4-25：倾盆非冻结降水":[[1,5,"浓雾","1d8小时"],[6,10,"浓雾","2d6小时"],[11,30,"大雨","2d6小时"],[31,60,"大雨","2d12小时"],[61,80,"大雨（低于40°F时为冻雨）","2d6小时"],[81,95,"雷暴","1d3小时"],[96,100,"雷暴","1d6小时"]],"表4-26：倾盆冻结降水":[[1,5,"浓雾","1d8小时"],[6,10,"浓雾","2d6小时"],[11,50,"大雪","1d4小时"],[51,90,"大雪","1d8小时"],[91,100,"大雪","2d12小时"]],"表4-27：雷暴风力":[[1,50,"强风"],[51,90,"烈风"],[91,100,"暴风"]],"表4-28：风力强度":[[1,50,"微风","每小时0–10英里","—/—","—","—","—"],[51,80,"常风","每小时11–20英里","—/—","—","—","—"],[81,90,"强风","每小时21–30英里","-2/—","超小型","—","-2"],[91,95,"烈风","每小时31–50英里","-4/—","小型","超小型","-4"],[96,100,"暴风","每小时51英里以上","不可能/-4","中型","小型","-8"]],"表4-29：云量":[[1,50,"无云"],[51,70,"薄云"],[71,85,"中等云量"],[86,100,"阴天"]]},"defs":{"寒冷":"寒冷气候见于世界极北或极南、纬度大于60度（距极点约2,000英里）的地区。在这些极地地区，一年中的大部分时间气温常低于冰点。这种气候的基线气温是寒冷：冬季20°F，春秋两季30°F，夏季可达40°F。距极点500英里以内的地区，基线气温比季节平均值低10°F。距极点250英里以内的地区，基线气温比季节平均值低20°F。由于冷空气往往比暖空气干燥，寒冷气候中降水的频率和强度各降低一级。","温带":"温带气候介于世界的极地地区与热带地区之间，纬度一般在60度到30度之间。这种气候的基线气温：冬季30°F，春秋两季60°F，夏季高达80°F。降水频率不会因温带气候而改变，但仍可能因海拔或季节等其他因素而改变（见下文）。","热带":"热带位于世界赤道两侧，向南北各延伸约30度纬度。热带地区往往温暖潮湿，基线气温：冬季50°F，春秋两季75°F，夏季可达95°F。由于温暖潮湿的空气会带来大量降水，这种气候中降水的频率和强度各提高一级。","海平面":"海平面和沿海地区的气温高10°。海平面地区的降水也往往比海拔较高的地区多，因此海平面地区的基线降水强度为重度。","低地":"低地是不靠海的低海拔地区，海拔一般在1,000尺到5,000尺之间。这一海拔范围不改变基线气温。低地的基线降水强度为中度。","高地":"高地包括海拔高于5,000尺的地区。高地的基线气温降低10°（不过在特别干旱平坦的地区，应改为基线气温升高10°；而在特别高海拔的地区，例如大型山脉，则应改为基线气温降低20°）。降水的频率降低一级，基线降水强度为中度。","降水频率":"降水频率分为五级：干旱、罕见、间歇、常见和持续。区域的基线降水频率由季节决定，但可以被气候和其他因素修正（例如见下文“沙漠”）。降水频率不能低于干旱，也不能高于持续。每天判定该日是否降水；降水发生的百分比几率汇总在表4-18：每日降水几率中。","降水强度":"基线降水强度取决于海拔，并可被气候修正。强度分四类。轻度降水是最低的强度，通常包括薄雾、微弱的毛毛雨或几片零星的雪花。中度降水表示明显但不至于干扰行动的降雨或降雪。重度降水通常是倾盆暴雨或大量降雪。倾盆降水是最高的强度，是一场倾泻而下的暴雨或暴雪，其状况可接近白茫茫一片的程度。降水强度不能低于轻度，也不能高于倾盆。","降水形态":"降水的结果不只是下雨。视强度和气温而定，降水可以从轻薄的雾或微弱的毛毛雨，一直到暴风雪或雷暴。一旦确定某一强度的降水正在发生，就掷1d12来确定降水事件从一天中的哪个钟点开始，再掷1d6判定是上午还是下午（1–3=上午，4–6=下午）。<br>接着，根据基线降水强度以及气温高于还是低于冰点（32°F），使用下方相应的表来生成具体的降水类型及其持续时间。（别忘了夜间气温更低！）降水对飞行生物能见度的影响，见下文[[#云量|云量]]一节。","毛毛雨":"毛毛雨将能见距离降至正常范围的四分之三，使察觉检定-2。它会自动熄灭微小的无遮掩火焰（蜡烛之类，但不包括火把）。","浓雾":"浓雾遮蔽5尺以外的一切视线，包括黑暗视觉。5尺外的生物具有[[隐蔽]]。浓雾通常出现在清晨、傍晚，有时也出现在夜间，但正午的热度通常会将其驱散。浓雾只在无风或微风时出现。","薄雾":"薄雾将能见距离降至正常范围的四分之三，使察觉检定-2、远程攻击-2。薄雾通常出现在清晨、傍晚，有时也出现在夜间，但正午的热度通常会将其驱散。薄雾只在无风或微风时出现。","中雾":"中雾将能见距离减半，使察觉检定-4、远程攻击-4。中雾通常出现在清晨、傍晚，有时也出现在夜间，但正午的热度通常会将其驱散。中雾只在无风或微风时出现。","雨":"雨将能见距离减半，使察觉检定-4。雨会自动熄灭无遮掩的火焰（蜡烛、火把等），并使远程攻击-4。","大雨":"大雨将能见距离降至正常范围的四分之一，使察觉检定-6。大雨会自动熄灭无遮掩的火焰，并使远程攻击-6。","冻雨":"冻雨本质上是冻结的雨，效果与小雪相同，但其积累通常在风暴结束后不会持续超过1–2小时。","大雪":"大雪将能见距离降至正常范围的四分之一，使察觉检定-6。大雪会熄灭无遮掩的火焰，并使远程攻击-6。大雪甚至在开始积起来之前就会妨碍移动：在大雪风暴中进入一格需要额外消耗1格（5尺）移动力（与难行地形叠加）。每小时大雪会在地面留下1d4英寸积雪。只要地面上至少还有2英寸积雪，进入积雪格就仍需额外消耗1格移动力。如果地面积雪至少有1尺，则进入积雪格改为需要额外消耗2格移动力。大雪风暴有10%的几率产生雷雪，而如果风力为烈风或更强，则有40%的几率变成暴风雪。","小雪":"小雪将能见距离降至正常范围的四分之三，使察觉检定-2。小雪每小时有75%的几率熄灭无遮掩的火焰，并使远程攻击-2。除非持续2小时或更久，小雪不会妨碍移动；持续到那时，进入这种积雪格需要额外消耗1格（5尺）移动力（与难行地形叠加）。每2小时小雪会在地面留下1英寸积雪。只要地面上至少还有2英寸积雪，进入积雪格就仍需额外消耗1格移动力。如果地面积雪至少有1尺，则进入积雪格改为需要额外消耗2格移动力。","中雪":"中雪将能见距离减半，使察觉检定-4。中雪会熄灭无遮掩的火焰，并使远程攻击-4。除非持续1小时，中雪不会妨碍移动；持续到那时，进入这种积雪格需要额外消耗1格（5尺）移动力（与难行地形叠加）。每小时中雪会在地面留下1英寸积雪。只要地面上至少还有2英寸积雪，进入积雪格就仍需额外消耗1格移动力。如果地面积雪至少有1尺，则进入积雪格改为需要额外消耗2格移动力。","雷暴":"雷暴带有强劲的风和大雨。要确定与雷暴相伴的风力类型，在表4-27：雷暴风力上掷骰。","沙漠":"沙漠出现在天气必须越过山脉、从而形成雨影的地方，以及极寒的环境中。沙漠的基线降水频率通常是干旱，但每年可有几周为罕见。","风力强度":"这是风力强度的类别。","风速":"这是出现的风速范围。风速在一天之中通常会在这些数值之间起伏；对于常风或更强的风力，一天中会有一些时段风速低于所列范围。","远程武器减值／攻城武器减值":"这是角色在所列强度的风中发射远程武器和攻城武器时承受的减值。在暴风强度的风中，普通远程武器攻击（无论是发射的还是投掷的）都不可能进行。这包括通过咒法系法术进行的远程攻击，但不包括塑能系远程攻击。攻城武器包括该类型的所有武器，以及巨人和其他具有投石特殊攻击的生物所投掷的巨石。","检定体型":"所列体型或更小的生物，除非通过DC 10的力量检定（在地面上）或DC 20的飞行检定（在空中），否则无法顶风前进。","吹走体型":"地面上所列体型的生物会被击倒，滚动1d4×10尺并受到2d6点非致命伤害，除非通过DC 15的力量检定。飞行的所列体型的生物会被吹退2d6×10尺，并因撞击和颠簸受到2d6点非致命伤害，除非通过DC 25的飞行检定。","技能减值":"这是可能受风影响的技能检定所承受的减值。这些减值始终适用于飞行检定和依赖声音的察觉检定，但GM也可以把它们用于[[特技]]检定、[[攀爬]]检定，以及任何可能被风力不利影响的其他属性或技能检定。","暴风雪":"烈风或更强的风与大雪相结合，可以形成暴风雪状况。暴风雪将视野范围降至不超过20尺，而且即使在这一范围内，生物的察觉检定仍承受-8减值。暴风雪中，降雪增加到每小时4英寸，而没有雪鞋或[[水面行走]]之类的能力，通常无法在超过3尺深的积雪中行进。此外，强风使人感觉（并对活体生物产生的影响）如同气温低了20°F。暴风雪有20%的几率持续2d12小时，而不是大雪的常规持续时间。","哈布沙暴":"哈布沙暴是由雷暴形成的沙暴。其效果见下文沙暴。","冰雹":"冰雹通常出现在雷暴之前不久或雷暴期间。冰雹不降低能见度，但冰雹落下的声响会使依赖声音的察觉检定承受-4减值。罕见情况下（5%几率），冰雹粒可以大到对暴露在外的生物和物体每分钟造成1d4点致命伤害。","飓风":"飓风是极其庞大的风暴，带有大雨，风力超过最强暴风的强度。飓风风速为每小时75–174英里，使远程攻击无法进行，攻城武器的攻击检定承受-8减值。大型或更小的生物必须通过DC 15的力量检定，否则无法顶风前进。地面上的中型或更小的生物必须通过DC 15的力量检定，否则会被击倒并滚动1d6×10尺，每滚动10尺受到1d6点非致命伤害。飞行生物必须通过DC 25的飞行检定，否则会被吹退2d8×10尺，并因撞击和颠簸受到4d6点非致命伤害。飓风通常还会引发洪水。要在飓风中出行而毫发无伤，几乎是不可能的。","沙暴":"在沙漠或类似的干旱环境中，烈风或更强的风卷起沙石时，就会出现沙暴。沙暴将能见距离降至1d10×10尺，身处其中的生物察觉检定承受-6减值。沙暴每小时对暴露在外的生物造成1d3点非致命伤害。","雷雪":"雪暴中的强风可以造成罕见的雷雪现象。雷雪中的雷击较少，但同样致命。风暴期间每小时，就有一道闪电随机击中一个无遮蔽的生物（野生动物和PC一样可能被击中）。被这道闪电击中的生物必须通过DC 18的反射豁免，否则受到10d8点电击伤害（豁免成功则伤害减半）。身穿金属护甲的生物在该反射豁免上承受-4减值。","龙卷风":"龙卷风的风速为每小时174–300英里，是致命的恐怖。最小的龙卷风占据半径20尺的爆发范围，并有暴风强度的风在该范围之外最远100尺的地方盘旋。最大的龙卷风可以是半径100尺的爆发范围，其暴风强度的风所在的半径延伸到该范围之外500尺。在龙卷风的核心爆发范围内，无法进行远程攻击，包括普通攻击、攻城武器攻击，甚至塑能系法术产生的攻击。超大型或更小的生物必须通过DC 20的力量检定，否则会被龙卷风的漏斗吸起；这会对该生物造成8d8点钝击、穿刺与挥砍的致命伤害。这一伤害无视除DR/epic、DR/—和硬度之外的一切减伤。造成这一伤害之后，龙卷风会把被吸起的生物向上、向远离龙卷风的方向抛出1d20×10尺，每抛出10尺造成1d6点坠落伤害。巨型及更大的生物会受到8d8点伤害，但不会被龙卷风移动。龙卷风的移动速度为40尺，但移动方向完全不可预测——你可以每轮随机决定其方向。龙卷风通常持续3d6分钟，但有些可以盘旋长达一小时。<br>大多数龙卷风由雷暴产生，但一些较小的龙卷风（通常是半径5到10尺的爆发范围，没有外围半径）可以出现在野火（火焰龙卷）、降雪（雪龙卷）或沙地（尘卷风）的地区。它们造成的伤害量相近，但火焰龙卷造成火焰伤害，雪龙卷造成寒冷伤害，尘卷风只造成钝击伤害，并且这几种龙卷风不会抛出目标。","野火":"野火可以由多种方式引燃，但就本规则而言，它们通常由闪电击中特别干燥的森林或其他植被区域而产生。使用[[野外#森林火灾 (CR 6)|森林火灾]]的规则，但增加10%的几率使火势产生1d6个火焰龙卷（见上文龙卷风）。"}},"天气":{"sec":{},"tab":{"表：随机天气":[[1,70,"正常天气","寒冷，无风","视季节而定 (※2)","炎热，无风"],[71,80,"反常天气","热浪 (01 – 30) 或者寒流 (31 – 100)","热浪 (01 – 50) 或者寒流 (51 – 100)","炎热，刮风"],[81,90,"严酷天气","降水 (降雪)","降水 (视季节而定)","炎热，刮风"],[91,99,"风暴","雪暴","雷暴，雪暴","沙尘暴"],[100,100,"强风暴","暴风雪","暴风雨，暴风雪，飓风，龙卷风","倾盆大雨"]],"表：风力效果":[[null,null,"微风","每小时0 – 10英里","– / –","–","–","–"],[null,null,"常风","每小时11 – 20英里","– / –","–","–","–"],[null,null,"强风","每小时21 – 30英里","–2 / –0","超小型","–","–2"],[null,null,"烈风","每小时31 – 50英里","–4 / –0","小型","超小型","–4"],[null,null,"暴风","每小时51 – 74英里","无效/ –40","中型","小型","–8"],[null,null,"飓风","每小时75 – 174英里","无效/ –80","大型","中型","–12"],[null,null,"龙卷风","每小时175 – 300英里","无效/无效","超大型","大型","–16"]]},"defs":{"无风":"空气流动速度缓慢 (时速0到10英里)。","寒冷":"白天气温通常从0°F到40°F，而夜间比白天温度低10到20°F。","[[寒流]]":"将原温度降低10°F。","大雨":"可以作为下雨处理 (请参考下文降水)，但是像浓雾一样会影响到可见度。另外大雨还有可能造成洪水 (请参考上文)。一场倾盆大雨通常会持续2d4小时。","热浪":"将原温度升高10°F。","炎热":"白天的气温从85°F到110°F，而夜间比白天温度低10°F到20°F。","均衡":"白天的气温从40°F到60°F，而夜间比白天温度低10到20°F。","强风暴 (暴风/暴风雪/飓风/龙卷风)":"风速超过50英里/小时 (请参考表：风力)。此外，暴风雪还会带来积雪 (1d3尺)，飓风则夹带着倾盆大雨 (请参考上文)。暴风雨通常能够持续1d6小时，暴风雪持续1d3天，而飓风可以刮上一个星期，但是它们对冒险的影响一般只持续1到2天，直到当强风暴的中心离开冒险区域。龙卷风的持续时间非常短暂 (1d6×10分钟)，它通常是雷暴的组成部分。","降水":"投掷百分骰以决定降水种类：雾 (01 – 30)，雨/雪 (31 – 90)，冻雨/冰雹 (91 – 00)。降雪与冻雨只有在温度等于或低于30°F的时候才会出现。大多数降水天气持续2d4小时。另外，冰雹一般只持续1d20分钟，但其经常伴随着1d4小时的降雨。","风暴 ([[沙尘暴]]/[[雪暴]]/雷暴)":"刮起烈风时 (时速30到50英里) 可视范围将减小至1/4。风暴一般持续 {2d4-1} 小时。请参考下文的详细描述。","温暖":"白天气温通常为60°F到85°F，而夜间比白天温度低10°F到20°F。","刮风":"风速由常风到强风 (时速10到30英里；请参考下页表：风力效果)。","降雨":"降雨使可视范围减半，同时使察觉检定-4。在雨中使用火焰、远程武器与察觉技能时与在烈风中效果同等。","降雪":"降雪天气中可视度、使用火焰、远程武器与察觉技能时与在烈风中效果同等。在被积雪覆盖的地面行走速度为正常速度的一半。一整天的降雪能形成1d6英吋深的积雪。","大雪":"大雪所造成的影响与降雪基本一致，但是对可视度的影响与起雾的天气同等 (请参考下文起雾)。一整天的大雪能形成1d4英尺深的积雪，在被大雪覆盖的地面行走速度为正常情况的1/4。大雪所伴随的强风或是烈风会卷起积雪，形成1d4×5尺深的雪堆，尤其是大型物体周围——例如小房子或是大[[帐篷]]。另外大量降雪的同时还会有10%的机率伴随着闪电 (请参考下文雷暴)。降雪对火焰的影响等同于常风。","冻雨":"实际上就是结冰的雨滴，冻雨在降落时可以视为普通降雨处理 (唯一不同之处在于冻雨熄灭有遮掩火焰的机率为75%)，落到地面后则当作降雪处理。","冰雹":"降雹对视线并无影响，但是冰雹砸向地面所发出的声音对基于听觉的察觉检定有很大影响 (-4)。有时 (5%机率) 巨大的冰雹能对室外物体造成1点致命伤害 (每次风暴)。降落到地面后，其对行动的影响与积雪无异。","沙尘暴 (CR 3)":"沙尘暴并不降水，取而代之的是大量的沙尘。狂风卷起的漫天尘土不但能将无遮掩的火源盖熄，同时还有50%的机率熄灭有遮掩的火源。沙尘暴总是伴随着烈风，在所经之处留下1d6 英吋厚的沙子。有时 (10%机率) 伴随沙尘暴的却是巨大的暴风 (参考表：风力效果)。如此巨大的沙尘暴每轮对暴露其中的生物造成1d3点[[非致命伤害]]，同时还能使该生物[[环境规则#窒息|窒息]] (参考溺水，只是如果该生物戴有头巾或是采取类似保护口鼻的措施，在10倍其体质属性轮后才开始窒息)。巨大的沙尘暴在经过的地区留下2d3-1尺的积沙。","雪暴":"除了像一般风暴那样伴随着降水和起风，雪暴还会在发生地区留下1d6英吋的积雪。","雷暴":"除了降水 (通常是降雨，但有时会下冰雹) 和起风，雷暴伴随着的闪电还能威胁到暴露在开阔地的生物 (尤其是穿戴金属盔甲的)。根据以往经验，为期1小时的风暴中心每分钟能产生1次闪电，每道闪电能造成4d8到10d8之间的电击伤害。雷暴有1/10的机率伴随着龙卷风。","强风暴":"疾风与[[瓢泼大雨]]般的降水能将可见度降低到0，察觉技能以及远程武器在强风暴中没有任何效果。无遮掩的火源自动熄灭，即使是有遮掩的火源也有75%的机率被熄灭。暴露在强风暴中的生物必须通过DC 20的强韧豁免，否则会受到强风暴的影响 (参考表：风力效果)。强风暴可以分为下列4种类型。","暴风":"强大的风力足以吹断树枝，暴风自动熄灭无遮盖的火焰并且有75%的机率熄灭有保护的火焰。远程武器攻击在这样风力的影响下根本没有作用，即使是攻城兵器的攻击检定也要承受-4减值。仅依靠听觉的察觉技能在暴风的狂号下变得非常困难，因此察觉检定-8。","暴雪":"暴雪发生时伴随着疾风与大雪 (通常1d3尺厚)，它带来的严寒对于无准备的生物是致命的。","飓风":"自动熄灭所有火焰。远程武器无效 (攻城兵器攻击检定-8)，并无法进行仅依靠听觉的察觉技能；角色只能听到飓风的呼号声。另外飓风还经常能折断树木。","龙卷风":"雷暴有1/10的机率伴随着龙卷风。除了骇人听闻的劲风，龙卷风会对被卷入其中的对象造成严重杀伤。","微风":"轻柔的空气波动，对游戏几乎没有任何影响。","常风":"持续、稳定的空气流动。有50%的机率能熄灭无遮盖的火苗，譬如蜡烛。","强风":"自动熄灭无遮盖的火焰 (蜡烛、火把等等)。并且使远程武器攻击检定和察觉检定-2。","烈风":"除了自动熄灭无遮盖的火焰外，这种强度的风力还能使有遮盖的火焰 (比如提灯) 不断闪动并且有50%的机率熄灭。远程武器攻击检定和察觉检定-4。此风力强度等同于[[造风术]]。","龙卷风 (CR 10)":"自动熄灭所有火焰。远程武器 (包括攻城兵器) 和察觉技能无效。接近龙卷风的角色如果力量检定失败，会被逐渐拖进而非被吹走。接触到龙卷风的生物会被吸离地面并飞速旋转1d10轮，在被抛出之前每轮受到6d6点伤害 (之后还要计算坠落伤害)。当龙卷风旋转速度达到每小时300英里时，其水平移动速度为每小时30英里 (大约每轮250尺)。龙卷风破坏力惊人，它能卷起树木、摧毁房屋并造成其他类似的巨大破坏。"}},"环境规则":{"寒害":["低温能对暴露其中的生物造成[[非致命伤害]]。如果不设法找个暖和的地方，寒冷造成的非致命伤害将无法恢复。一旦角色因为非致命伤害过重而导致[[昏迷]]，他将会开始以同样的速度受到正常伤害。","暴露在寒冷环境下的生物 (低于40°F) 每小时必须进行强韧检定（DC 15，每增加一次检定再+1），失败则受到1d6点非致命伤害。拥有生存技能的角色可以在检定上获得加值，而且可以将该加值应用在其他队友的检定上 (请参考技能描述)。","暴露在严寒环境下的生物 (低于0°F) 每10分钟必须进行强韧检定（DC 15，每增加一次检定再+1），失败则受到1d6点非致命伤害。拥有生存技能的角色可以在检定上获得加值，而且可以将该加值应用在其他队友的检定上。身着冬衣的角色只需每小时进行检定。","受到低温造成的非致命伤害的角色，将会由于[[冻伤]]或体温过低而陷入[[疲乏]]。这些效果直到低温造成的非致命伤害完全消失才能恢复。","极度严寒 (低于-20°F) 每分钟受到1d6点致命伤害 (无豁免)。此外，角色每分钟必须进行强韧检定（DC 15，每增加一次检定再+1） 失败则受到1d4点非致命伤害。"],"热害":["高温会对角色造成非致命伤害，而且如不设法降低温度 (比如躲避到阴凉处、坚持到黄昏时间、浸在水中避暑或者是接受[[忍受环境]]法术效果等等) 非致命伤害不会恢复。一旦角色因为非致命伤害过重而导致昏迷，他将会开始以同样的速度受到正常伤害。","处于炎热环境下 (超过 90°F) 的角色必须每小时进行一次强韧检定（DC 15，每增加一次检定再+1），失败则受到1d4点非致命伤害。穿着厚重衣物或盔甲的角色在进行检定时需要承受-4的减值。拥有生存技能的角色可以在检定上获得加值，而且可以将该加值应用在其他队友的检定上。如果角色陷入昏迷状态，那么他将受到正常伤害 (每小时1d4)。","处于高温环境下的角色 (超过110°F)，必须每10分钟进行一次强韧检定（DC 15，每增加一次检定再+1），失败则受到1d4点非致命伤害。穿着厚重衣物或盔甲的角色在进行检定时需要承受-4的减值。拥有生存技能的角色可以在检定上获得加值，而且可以将该加值应用在其他队友的检定上。如果角色陷入昏迷状态，那么他将受到正常伤害 (每10分钟1d4)。","受到高温造成的非致命伤害的角色将会由于中暑而进入疲乏状态。这些效果直到高温造成的非致命伤害完全消失才能恢复。","极度高温 (气温高于140°F，或是火焰，沸腾的水，火山熔岩) 能造成正常伤害。吸入极度高温的气体每分钟会受到1d6点伤害 (无豁免)。此外，每5分钟角色必须进行强韧检定（DC 15，每增加一次检定再+1），失败则受到1d4点非致命伤害。穿着厚重衣物或盔甲的角色在进行检定时需要承受-4的减值。","沸腾的水能造成1d6点烫伤，如果角色全身都浸入沸腾的水中，每轮将受到10d6点伤害。"]}}]=====]